new_string:
String? _activePetDisplayNickname() {
  final name = _activePet?['nickname']?.toString().trim();
  if (name == null || name.isEmpty) return null;
  return name;
}

String _activePetDisplayName(AppLocalizations l10n) {
  return _activePetDisplayNickname() ?? l10n.interactionPetNameFallback;
}

bool _hasEligibleMealForToyPlay() {
  return _todayMealLogs.any((row) {
    final resultType = row['result_type']?.toString().trim().toLowerCase();
    return resultType == 'perfect' || resultType == 'good';
  });
}

String _interactionPlaySuccessMessage({required int affectionGain}) {
  final l10n = AppLocalizations.of(context);
  final petName = _activePetDisplayName(l10n);
  final petNameTopic = _isEnglishLocale
      ? petName
      : _petNameWithTopicParticle(petName);
  return _pickInteractionTemplate([
    l10n.interactionPlaySuccess1(petNameTopic, affectionGain),
    l10n.interactionPlaySuccess2(petNameTopic, affectionGain),
  ]);
}

String _interactionPlayFailureMessage() {
  final l10n = AppLocalizations.of(context);
  final petName = _activePetDisplayName(l10n);
  final petNameTopic = _isEnglishLocale
      ? petName
      : _petNameWithTopicParticle(petName);
  return _pickInteractionTemplate([
    l10n.interactionPlayFailure1(petNameTopic),
    l10n.interactionPlayFailure2(petNameTopic),
  ]);
}

String _interactionPettingSuccessMessage({required int affectionGain}) {
  final l10n = AppLocalizations.of(context);
  final petName = _activePetDisplayName(l10n);
  final petNameSubject = _isEnglishLocale
      ? petName
      : _petNameWithSubjectParticle(petName);
  final family = _activePetFamily();
  if (family == 'cat') {
    return _pickInteractionTemplate([
      l10n.interactionPettingCat1(petNameSubject, affectionGain),
      l10n.interactionPettingCat2(petName, affectionGain),
    ]);
  }
  // dog 및 미분류는 강아지 문구 사용.
  return _pickInteractionTemplate([
    l10n.interactionPettingDog1(petNameSubject, affectionGain),
    l10n.interactionPettingDog2(petName, affectionGain),
  ]);
}
